select t0.belnr_id as 'Order Number',t1.BELPOS_ID as 'Sub order number',t0.beldat 'Order Date',t0.typ as 'Type', t1.itemcode as 'Finished Good',t1.MENGE_VERBRAUCH as 'Plan Fiished QTY',t1.GEL_MENGE as 'Actual finished Qty',t2.Art1_id as 'Material' ,t2.TOTALQUANTITY_WHUNIT as 'Plan QTY',t2.BookedQty as 'Actual QTY',t1.abgkz_date as 'Wo closed',t1.zusatztext as 'Remarks'from beas_fthaupt t0 inner join beas_ftpos t1 on t0.BELNR_ID = t1.BELNR_IDinner join beas_ftstl t2 on t1.BELNR_ID = t2.BELNR_ID and t1.BELPOS_ID = t2.BELPOS_ID